package com.star4droid.star2d.icons;

import android.content.Context;
import android.graphics.Path;

import com.google.gson.stream.JsonReader;
import com.star4droid.star2d.evo.star2dApp;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;

/**
 * The built-in icon library (assets/icons/catalog.json, generated by tools/make_icons.py from Material Design Icons, Apache-2.0).
 * Icons are single-path 24x24 glyphs. Thread-safe after loading; any thread may call everything here.
 */
public final class IconCatalog {
    public static final String ASSET = "icons/catalog.json";

    /** One icon. {@link #id} is lower-case letters, digits and '-'. */
    public static final class Icon {
        public final String id;
        /** Index in {@link IconCatalog#categories()}. */
        public final int category;
        /** Extra search words (space separated, English). The words of the id are searched too. */
        public final String tags;
        /** SVG path data in a {@link #viewBox} x {@link #viewBox} box. */
        public final String pathData;
        /** 0 = "ui" (Material Design Icons), 1 = "game" (game-icons.net). */
        public final int set;
        /** Edge of the square the path coordinates live in: 24 for the ui set, 512 for the game set. */
        public final int viewBox;
        final String[] idTokens;
        final String[] tagTokens;
        private Path path;

        Icon(String id, int category, String tags, String pathData, int set, int viewBox) {
            this.set = set;
            this.viewBox = viewBox;
            this.id = id;
            this.category = category;
            this.tags = tags;
            this.pathData = pathData;
            this.idTokens = id.split("-");
            this.tagTokens = tags.isEmpty() ? new String[0] : tags.split(" ");
        }

        /** The parsed path in viewBox units (do not modify: copy it first). Null if the data cannot be parsed. */
        public synchronized Path path() {
            if (path == null) {
                try {
                    path = androidx.core.graphics.PathParser.createPathFromPathData(pathData);
                } catch (Throwable ignored) {
                }
            }
            return path;
        }

        /** Default file name stem when imported: icon_heart_broken. */
        public String defaultName() {
            return "icon_" + id.replace('-', '_');
        }
    }

    private static IconCatalog instance;

    public static final String[] SET_NAMES = {"ui", "game"};

    private final List<String> categories = new ArrayList<>();
    private final List<Icon> icons = new ArrayList<>();
    private final HashMap<String, Icon> byId = new HashMap<>();

    private IconCatalog() {}

    /** Loads the catalog once (about 1300 icons, a few ms to parse). */
    public static synchronized IconCatalog get(Context c) {
        if (instance == null) {
            IconCatalog cat = new IconCatalog();
            try (InputStream in = c.getAssets().open(ASSET)) {
                cat.read(in);
            } catch (Exception e) {
                throw new RuntimeException("icon catalog: " + e);
            }
            instance = cat;
        }
        return instance;
    }

    public static IconCatalog get() {
        return get(star2dApp.getContext());
    }

    private void read(InputStream in) throws Exception {
        try (JsonReader r = new JsonReader(new InputStreamReader(in, StandardCharsets.UTF_8))) {
            r.beginObject();
            while (r.hasNext()) {
                String k = r.nextName();
                if (k.equals("categories")) {
                    r.beginArray();
                    while (r.hasNext()) categories.add(r.nextString());
                    r.endArray();
                } else if (k.equals("icons")) {
                    r.beginArray();
                    while (r.hasNext()) {
                        String id = "", t = "", p = "";
                        int c = 0, st = 0, w = 24;
                        r.beginObject();
                        while (r.hasNext()) {
                            switch (r.nextName()) {
                                case "i": id = r.nextString(); break;
                                case "c": c = r.nextInt(); break;
                                case "s": st = r.nextInt(); break;
                                case "w": w = r.nextInt(); break;
                                case "t": t = r.nextString(); break;
                                case "p": p = r.nextString(); break;
                                default: r.skipValue();
                            }
                        }
                        r.endObject();
                        Icon ic = new Icon(id, c, t, p, st, w);
                        icons.add(ic);
                        byId.put(id, ic);
                    }
                    r.endArray();
                } else {
                    r.skipValue();
                }
            }
            r.endObject();
        }
    }

    public List<String> categories() {
        return Collections.unmodifiableList(categories);
    }

    public List<Icon> all() {
        return Collections.unmodifiableList(icons);
    }

    public int size() {
        return icons.size();
    }

    public Icon byId(String id) {
        if (id == null) return null;
        String k = id.trim().toLowerCase(Locale.ROOT).replace('_', '-').replace(' ', '-');
        if (k.startsWith("icon-")) {
            Icon i = byId.get(k.substring(5));
            if (i != null) return i;
        }
        return byId.get(k);
    }

    /** Number of icons per category (same order as {@link #categories()}), over both sets. */
    public int[] counts() {
        return counts(-1);
    }

    /** Number of icons per category inside one set (-1 = both). */
    public int[] counts(int set) {
        int[] n = new int[categories.size()];
        for (Icon i : icons) if ((set < 0 || i.set == set) && i.category >= 0 && i.category < n.length) n[i.category]++;
        return n;
    }

    /** Number of icons in a set (-1 = all). */
    public int size(int set) {
        if (set < 0) return icons.size();
        int n = 0;
        for (Icon i : icons) if (i.set == set) n++;
        return n;
    }

    /** "ui" / "game" (case-insensitive, also "material", "games", "all"...) -> 0 / 1; "" or "all" -> -1; unknown -> -2. */
    public static int setIndex(String name) {
        if (name == null) return -1;
        String n = name.trim().toLowerCase(Locale.ROOT);
        if (n.isEmpty() || n.equals("all") || n.equals("any") || n.equals("both")) return -1;
        if (n.equals("ui") || n.equals("material") || n.equals("mdi") || n.equals("0")) return 0;
        if (n.equals("game") || n.equals("games") || n.equals("game-icons") || n.equals("gameicons") || n.equals("1")) return 1;
        return -2;
    }

    /**
     * Search: every word of the query has to match (id words and tags). Ranking: the whole query equals the id, then id starts
     * with it, then word matches (exact > prefix > substring > one typo), id words weigh more than tags, simpler (shorter) ids first.
     *
     * @param category index in {@link #categories()} or -1 for all
     * @param set      0 ui, 1 game, -1 both (with the same match quality the ui set comes first)
     */
    public List<Icon> search(String query, int category, int limit) {
        return search(query, category, -1, limit);
    }

    /** Same, restricted to one set (0 = ui, 1 = game, -1 = both). */
    public List<Icon> search(String query, int category, int set, int limit) {
        String q = query == null ? "" : query.trim().toLowerCase(Locale.ROOT);
        ArrayList<Icon> out = new ArrayList<>();
        if (q.isEmpty()) {
            for (Icon i : icons) {
                if (category >= 0 && i.category != category) continue;
                if (set >= 0 && i.set != set) continue;
                out.add(i);
                if (limit > 0 && out.size() >= limit) break;
            }
            return out;
        }
        String whole = q.replace(' ', '-').replace('_', '-');
        String[] terms = q.split("[^a-z0-9]+");
        ArrayList<String> ts = new ArrayList<>();
        for (String t : terms) if (!t.isEmpty()) ts.add(t);
        if (ts.isEmpty()) return out;
        ArrayList<Object[]> scored = new ArrayList<>();
        for (Icon i : icons) {
            if (category >= 0 && i.category != category) continue;
            if (set >= 0 && i.set != set) continue;
            int score = 0;
            boolean ok = true;
            for (String t : ts) {
                int s = termScore(i, t);
                if (s == 0) {
                    ok = false;
                    break;
                }
                score += s;
            }
            if (!ok) continue;
            if (i.id.equals(whole)) score += 1000;
            else if (i.id.startsWith(whole)) score += 200;
            else if (i.id.contains(whole)) score += 60;
            // fewer words in the id = a more basic icon
            score -= i.idTokens.length * 3;
            scored.add(new Object[]{i, score});
        }
        Collections.sort(scored, (a, b) -> {
            int d = (Integer) b[1] - (Integer) a[1];
            return d != 0 ? d : ((Icon) a[0]).id.compareTo(((Icon) b[0]).id);
        });
        for (Object[] s : scored) {
            out.add((Icon) s[0]);
            if (limit > 0 && out.size() >= limit) break;
        }
        return out;
    }

    private static int termScore(Icon i, String t) {
        int best = 0;
        String stem = stem(t);
        for (String w : i.idTokens) best = Math.max(best, wordScore(w, t, stem, 70, 45, 25));
        for (String w : i.tagTokens) best = Math.max(best, wordScore(w, t, stem, 50, 32, 14));
        return best;
    }

    private static int wordScore(String w, String t, String stem, int exact, int prefix, int contains) {
        if (w.equals(t) || w.equals(stem)) return exact;
        if (w.startsWith(t) || (stem.length() >= 3 && w.startsWith(stem))) return prefix;
        if (t.length() >= 3 && w.contains(t)) return contains;
        if (t.length() >= 4 && Math.abs(w.length() - t.length()) <= 1 && editDistanceAtMost1(w, t)) return 8;
        return 0;
    }

    /** "hearts" -> "heart", "boxes" -> "box". */
    private static String stem(String t) {
        if (t.length() > 4 && t.endsWith("ies")) return t.substring(0, t.length() - 3) + "y";
        if (t.length() > 4 && t.endsWith("es")) return t.substring(0, t.length() - 2);
        if (t.length() > 3 && t.endsWith("s")) return t.substring(0, t.length() - 1);
        return t;
    }

    private static boolean editDistanceAtMost1(String a, String b) {
        int la = a.length(), lb = b.length();
        if (Math.abs(la - lb) > 1) return false;
        int i = 0, j = 0, diff = 0;
        while (i < la && j < lb) {
            if (a.charAt(i) == b.charAt(j)) {
                i++;
                j++;
                continue;
            }
            if (++diff > 1) return false;
            if (la > lb) i++;
            else if (lb > la) j++;
            else {
                i++;
                j++;
            }
        }
        return diff + (la - i) + (lb - j) <= 1;
    }
}
